# vsym.py -- v-nc-gain: the symmetry facts behind Lemma 1 / Lemma 2 (orbit variables, averaging), on my own Gamma_m.
#  Sp(2m,2) generated by transvections x -> x + w(x,v) v; check (i) they are automorphisms of Gamma_m, (ii) transitive
#  on ordered opposite pairs, (iii) transitive on arcs; and the uniform cut value c_2 = 3/2 by enumerating all cuts.
import sys, numpy as np, itertools
sys.path.insert(0, '.')
import vgamma

def perms(g):
    m = g.m; idx = {S: i for i, S in enumerate(g.L)}; out = []
    for v in range(1, 1 << (2 * m)):
        out.append(np.array([idx[frozenset(x ^ (v if vgamma.w(x, v, m) else 0) for x in S)] for S in g.L]))
    return out

def orbit_pairs(g, P, mask):
    """BFS orbit of the pair (0, first t with mask) under the generators; returns orbit size and target set size."""
    n = g.n
    seen = np.zeros((n, n), bool)
    s0 = 0; t0 = int(np.nonzero(mask[0])[0][0]); seen[s0, t0] = True
    fr_s = np.array([s0]); fr_t = np.array([t0])
    while len(fr_s):
        ns, nt = [], []
        for p in P:
            a = p[fr_s]; b = p[fr_t]
            new = ~seen[a, b]
            a, b = a[new], b[new]
            if len(a):
                seen[a, b] = True; ns.append(a); nt.append(b)
        if ns:
            fr_s = np.concatenate(ns); fr_t = np.concatenate(nt)
            key = np.unique(fr_s * n + fr_t); fr_s, fr_t = key // n, key % n
        else: fr_s = np.array([], int)
    return int(seen.sum()), int(mask.sum()), bool((seen <= mask).all())

if __name__ == '__main__':
    for m in map(int, sys.argv[1:]):
        g = vgamma.VG(m); P = perms(g)
        A = (g.D == 1)
        auto = all((A[np.ix_(p, p)] == A).all() for p in P)
        o_opp = orbit_pairs(g, P, g.D == m)
        o_arc = orbit_pairs(g, P, g.D == 1)
        print(f"m={m}: {len(P)} transvections, all automorphisms: {auto}; orbit of an ordered opposite pair {o_opp[0]} of {o_opp[1]} "
              f"(inside: {o_opp[2]}); orbit of an arc {o_arc[0]} of {o_arc[1]} (inside: {o_arc[2]})", flush=True)
        if m == 2:
            n = g.n; best = 0; bestQ = None
            from fractions import Fraction
            for mask in range(1, (1 << n) - 1):
                q = np.array([(mask >> i) & 1 for i in range(n)], bool)
                sepd = int((g.D[np.ix_(~q, q)] == m).sum())       # ordered (s,t): s out, t in
                arcin = int(A[np.ix_(~q, q)].sum())
                r = Fraction(sepd, arcin)
                if r > best: best, bestQ = r, q.sum()
            nA = int(A.sum()); NU = int((g.D == m).sum())
            print(f"m=2 uniform directed cut value per session: max_Q sep/arcs_in = {best} (|Q| = {bestQ}) -> c_2 = {best * nA / NU} (claimed 3/2)")
